{
  "primary_meaning": "Sacred rest and cessation from labor, commemorating God's rest after creation and signifying the believer's spiritual rest and salvation-rest fulfilled in Christ",
  "primary_basis": [
    "Genesis 2:2-3",
    "Exodus 20:8-11",
    "Deuteronomy 5:12-15",
    "Matthew 11:28-30",
    "Mark 2:27-28",
    "Hebrews 3:7-4:11",
    "Colossians 2:16-17"
  ],
  "alternatives": [
    {
      "meaning": "Perpetual sign of the Mosaic covenant and mark of Israel's distinct identity/election",
      "basis": ["Exodus 31:12-17", "Ezekiel 20:12", "Ezekiel 20:20"],
      "prominence": "common"
    },
    {
      "meaning": "Type or shadow of the coming messianic/eschatological age and final eternal rest",
      "basis": ["Hebrews 4:1-11", "Colossians 2:16-17", "Revelation 14:13"],
      "prominence": "common"
    },
    {
      "meaning": "Memorial of deliverance from Egyptian bondage and liberation",
      "basis": ["Deuteronomy 5:12-15"],
      "prominence": "minority"
    },
    {
      "meaning": "Ongoing literal seventh-day observance still binding as moral law (Sabbatarian reading)",
      "basis": ["Exodus 20:8-11", "Isaiah 66:22-23", "Matthew 5:17-19"],
      "prominence": "minority"
    },
    {
      "meaning": "Transferred or fulfilled in the Lord's Day (Sunday) as Christian celebration of resurrection",
      "basis": ["Acts 20:7", "1 Corinthians 16:2", "Revelation 1:10", "early patristic practice"],
      "prominence": "common"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Christian interpretation overwhelmingly centers on the rest motif (creational, soteriological, and eschatological), with broad agreement that the Sabbath functions typologically toward Christ even while debates persist over continuing literal observance versus fulfillment/transfer. The core symbolic association with rest is stable across traditions."
}
